/**
 * M4 wire-graph extraction: pure transform of flow JSON (an array of
 * Node-RED node config objects) into a minimal wire graph keyed by node id.
 *
 * Only the wire graph (plain id-string arrays) is ever passed to the
 * Workflow - never full node configs.
 */

"use strict";

/**
 * @param {Array<object>} flows - flow JSON, e.g. as read by bootstrap.js
 * @returns {Object<string, Array<Array<string>>>} nodeId -> wires (array of
 *   output-port arrays of destination node ids). Nodes without a `wires`
 *   property (tabs, config nodes, etc.) are omitted.
 */
function extractWireGraph(flows) {
    var graph = {};
    (flows || []).forEach(function(node) {
        if (node && Object.prototype.hasOwnProperty.call(node, "wires")) {
            graph[node.id] = node.wires.map(function(port) {
                return port.slice();
            });
        }
    });
    return graph;
}

/**
 * M9/issue-6 node-metadata extraction: pure transform of flow JSON into a
 * minimal id -> {name, type} map, for Temporal UI observability only
 * (Activity `summary`/`activityId` labeling in workflows.js). Deliberately
 * mirrors extractWireGraph's node selection (only nodes with a `wires`
 * property - i.e. actual flow nodes, not tabs/config nodes) and extracts
 * ONLY `name`/`type` - never full node configs/credentials.
 *
 * @param {Array<object>} flows - flow JSON, e.g. as read by bootstrap.js
 * @returns {Object<string, {name:(string|undefined), type:(string|undefined)}>}
 */
function extractNodeMeta(flows) {
    var meta = {};
    (flows || []).forEach(function(node) {
        if (node && Object.prototype.hasOwnProperty.call(node, "wires")) {
            meta[node.id] = { name: node.name, type: node.type };
        }
    });
    return meta;
}

module.exports = { extractWireGraph, extractNodeMeta };
